INSERT INTO `fa_user_character_dialogue` VALUES (1,10043,73,6401,'Hi','Hey! Good to see you\'re still around.',1769840194,1769840194),(2,10043,73,0,'你好','嗨,你最喜欢的颜色是什么?',1769840222,1769840222),(3,10043,73,0,'不喜欢什么颜色','没关系 你可以用过滤器',1769840237,1769840237),(4,10043,73,0,'你叫什么','他叫卡马里',1769840251,1769840251),(5,10043,73,0,'你很漂亮','谢谢!',1769840269,1769840269),(6,10043,73,6386,'what？','What? No',1769840294,1769840294),(7,10043,73,6180,'HOW  old are you','He\'s a troll. Just ignore him. He has negative karma.',1769840367,1769840367),(8,10043,73,6324,'You\'re pretty.','Je suis disponible maintenant, si vous l\'êtes.',1769840745,1769840745),(9,10043,73,6340,'You look great','Thank you! You too.',1769840873,1769840873),(10,10043,73,6487,'Who are you?','I am a person.',1769841079,1769841079),(11,10043,73,6487,'What\'s your name?','It\'s the same as my username here.',1769841178,1769841178),(12,10043,73,0,'Where are you from?','I\'m from the UK, I got it in the US for about 20',1769841780,1769841780),(13,10043,73,6315,'I like you.','thanks! i have a few more that are awesome, but these are the ones I\'m most proud of.',1769841863,1769841863),(14,10043,73,0,'Where are you from?','West Coast.',1769841880,1769841880),(15,10043,73,6239,'How are you','I\'m good, thanks. How about yourself?',1770283638,1770283638),(16,10043,73,0,'我爱你。','谢谢 你太客气了',1770283655,1770283655),(17,10043,73,0,'你可以多说一些话吗','你们想听什么?',1770283688,1770283688),(18,10043,73,0,'爱我的话','我不爱你',1770283700,1770283700),(19,10043,73,0,'为什么？','我试过了 但价格对我来说太高了',1770283710,1770283710),(20,10043,73,0,'什么价格太高了？','我觉得好像是20万',1770283725,1770283725),(21,10043,73,0,'什么20万？','. . . . . 千美元.',1770283741,1770283741),(22,10043,73,0,'你在说什么？','我想他是在引用几天前这篇文章 究竟发生了什么事情',1770283760,1770283760),(23,10043,73,0,'可以发给我你的照片嘛','我现在在上班 但如果我记得我回家后会贴的',1770283795,1770283795),(24,10043,73,0,'你在哪里上班？','他是个律师',1770283812,1770283812),(25,10047,73,6302,'Hey sexy I have taped your mouth fully with tape covered hands tied behind your back already in your lace bra underwear','How did you get that shirt?',1770896671,1770896671),(26,10047,73,6339,'Lol ?','Creo que el objetivo de este submarino es ser gracioso...',1770896685,1770896685),(27,10047,73,6465,'Shut up','You shut up.',1770896695,1770896695),(28,10047,73,0,'Sorry do you want to play duct tape challenge','I think I\'m good, thanks though.',1770896707,1770896707);
